class UpperCaseConverter implements AttributeConverter<String,String> {
    public String convertToDatabaseColumn(String s) { return s == null ? null : s.toUpperCase(); }
    public String convertToEntityAttribute(String s) { return s; }
}
@Convert(converter = UpperCaseConverter.class) String title;

