class DateConverter implements AttributeConverter<LocalDate,String> {
    DateTimeFormatter fmt = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    public String convertToDatabaseColumn(LocalDate d) { return d.format(fmt); }
    public LocalDate convertToEntityAttribute(String s) { return LocalDate.parse(s, fmt); }
}

class YesNoConverter implements AttributeConverter<Boolean,String> {
    public String convertToDatabaseColumn(Boolean b) { return b ? "Y" : "N"; }
    public Boolean convertToEntityAttribute(String s) { return "Y".equals(s); }
}

class MapConverter implements AttributeConverter<Map<String,String>,String> {
    public String convertToDatabaseColumn(Map<String,String> m) {
        return m.entrySet().stream().map(e -> e.getKey()+"="+e.getValue()).collect(Collectors.joining(";"));
    }
    public Map<String,String> convertToEntityAttribute(String s) {
        Map<String,String> m = new HashMap<>();
        for (String pair : s.split(";")) { String[] kv = pair.split("="); m.put(kv[0], kv[1]); }
        return m;
    }
}

class PriorityConverter implements AttributeConverter<Priority,Integer> {
    public Integer convertToDatabaseColumn(Priority p) { return switch(p) { case LOW -> 10; case MEDIUM -> 20; case HIGH -> 30; }; }
    public Priority convertToEntityAttribute(Integer i) { return switch(i) { case 10 -> Priority.LOW; case 20 -> Priority.MEDIUM; case 30 -> Priority.HIGH; default -> throw new IllegalArgumentException(); }; }
}

// ORDINAL: priority=2
// STRING: priority='HIGH'
// wlasny konwerter: priority=30

