enum OrderStatus {
    NEW, PAID, SHIPPED, DELIVERED, CANCELLED;
    boolean canTransitionTo(OrderStatus next) {
        return switch (this) { case NEW -> next == PAID || next == CANCELLED; case PAID -> next == SHIPPED; default -> false; };
    }
}
if (!current.canTransitionTo(next)) throw new IllegalStateException("Niedozwolone przejscie");

class CachedConverter implements AttributeConverter<X,String> {
    Map<String,X> cache = new HashMap<>();
    public X convertToEntityAttribute(String s) {
        return cache.computeIfAbsent(s, key -> { try { Thread.sleep(1); } catch (Exception e) {} return parse(key); });
    }
}

class ReverseConverter implements AttributeConverter<String,String> {
    public String convertToDatabaseColumn(String s) { return new StringBuilder(s).reverse().toString(); }
    public String convertToEntityAttribute(String s) { return new StringBuilder(s).reverse().toString(); }
}
